# Use an absolute database path so changing the working directory or replacing app.py
# never silently creates a second empty SQLite database.
BASE_DIR = os.path.dirname(os.path.abspath(__file__))
DATABASE_DIR = os.path.join(BASE_DIR, "database")
DATABASE = os.path.join(DATABASE_DIR, "parish_records.db")
BACKUP_DIR = os.path.join(DATABASE_DIR, "backups")
DATABASE_URL = os.getenv("DATABASE_URL", "").strip()
USING_POSTGRES = bool(DATABASE_URL)

# DATA SAFETY: changing application code must never reset parish records.
# SQLite is used locally. Render deployments should use DATABASE_URL (PostgreSQL)
# or another persistent database; Render's normal service filesystem is temporary.
def _sqlite_record_count(path):
    if not os.path.exists(path):
        return 0
    try:
        conn = sqlite3.connect(path)
        cur = conn.cursor()
        exists = cur.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='records'").fetchone()
        count = cur.execute("SELECT COUNT(*) FROM records").fetchone()[0] if exists else 0
        conn.close()
        return int(count or 0)
    except Exception:
        return 0

def create_safety_backup(reason="startup"):
    """Copy a non-empty SQLite database before schema/code changes. Never overwrites live DB."""
    if USING_POSTGRES or not os.path.exists(DATABASE):
        return None
    if _sqlite_record_count(DATABASE) <= 0:
        return None
    try:
        os.makedirs(BACKUP_DIR, exist_ok=True)
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        backup_path = os.path.join(BACKUP_DIR, f"parish_records_auto_{reason}_{stamp}.db")
        source = sqlite3.connect(DATABASE)
        destination = sqlite3.connect(backup_path)
        with destination:
            source.backup(destination)
        destination.close(); source.close()
        # Keep the newest 30 automatic backups.
        backups = sorted([f for f in os.listdir(BACKUP_DIR) if f.startswith("parish_records_auto_") and f.endswith(".db")])
        for filename in backups[:-30]:
            try: os.remove(os.path.join(BACKUP_DIR, filename))
            except OSError: pass
        return backup_path
    except Exception as exc:
        print(f"DATABASE SAFETY BACKUP WARNING: {exc}")
        return None

def ensure_sqlite_schema(connection):
    """Non-destructive schema migration: only adds missing columns, never drops records/tables."""
    migrations = {
        "records": {
            "date_of_death": "TEXT",
            "cause_of_death": "TEXT",
            "age": "TEXT",
            "civil_status": "TEXT",
            "record_details": "TEXT",
        }
    }
    for table, columns in migrations.items():
        try:
            existing = {row[1] for row in connection.execute(f"PRAGMA table_info({table})").fetchall()}
            for column, column_type in columns.items():
                if column not in existing:
                    connection.execute(f"ALTER TABLE {table} ADD COLUMN {column} {column_type}")
        except Exception as exc:
            print(f"DATABASE MIGRATION WARNING ({table}): {exc}")

