class DBConnection:
    """Small compatibility layer: SQLite locally, PostgreSQL on Render."""
    def __init__(self):
        self.is_postgres = USING_POSTGRES
        if self.is_postgres:
            self.conn = psycopg2.connect(DATABASE_URL, sslmode="require")
        else:
            os.makedirs(DATABASE_DIR, exist_ok=True)
            self.conn = sqlite3.connect(DATABASE)
            self.conn.row_factory = sqlite3.Row

    def execute(self, query, params=()):
        if self.is_postgres:
            query = query.replace("?", "%s")
            cur = self.conn.cursor(cursor_factory=DictCursor)
            cur.execute(query, params)
            return cur
        return self.conn.execute(query, params)

    def cursor(self):
        if self.is_postgres:
            return self.conn.cursor(cursor_factory=DictCursor)
        return self.conn.cursor()

    def commit(self):
        self.conn.commit()

    def close(self):
        self.conn.close()


def get_db_connection():
    return DBConnection()


def initialize_database():
    # Snapshot existing non-empty local database before any startup migration.
    create_safety_backup("before_update")
    connection = get_db_connection()
    if USING_POSTGRES:
        schemas = [
            """CREATE TABLE IF NOT EXISTS records (
                id SERIAL PRIMARY KEY, record_type TEXT NOT NULL, full_name TEXT NOT NULL,
                date_of_birth TEXT, date_of_record TEXT, father_name TEXT, mother_name TEXT,
                spouse_name TEXT, notes TEXT, record_details TEXT)""",
            """CREATE TABLE IF NOT EXISTS users (
                id SERIAL PRIMARY KEY, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL,
                role TEXT NOT NULL DEFAULT 'Staff')""",
            """CREATE TABLE IF NOT EXISTS login_activity (
                id SERIAL PRIMARY KEY, user_id INTEGER, username TEXT NOT NULL, action TEXT NOT NULL, timestamp TEXT NOT NULL)""",
            """CREATE TABLE IF NOT EXISTS record_activity (
                id SERIAL PRIMARY KEY, user_id INTEGER, username TEXT NOT NULL, action TEXT NOT NULL,
                record_id INTEGER, record_type TEXT, record_name TEXT, timestamp TEXT NOT NULL)""",
            """CREATE TABLE IF NOT EXISTS certificate_requests (
                id SERIAL PRIMARY KEY, request_number TEXT UNIQUE NOT NULL, certificate_type TEXT NOT NULL,
                full_name TEXT NOT NULL, date_of_birth TEXT, father_name TEXT, mother_name TEXT, spouse_name TEXT,
                date_of_record TEXT, purpose TEXT, copies INTEGER NOT NULL DEFAULT 1, contact_information TEXT NOT NULL,
                status TEXT NOT NULL DEFAULT 'Pending', staff_notes TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL)""",
            """CREATE TABLE IF NOT EXISTS certificate_request_activity (
                id SERIAL PRIMARY KEY, request_id INTEGER NOT NULL, request_number TEXT NOT NULL, username TEXT NOT NULL,
                action TEXT NOT NULL, old_status TEXT, new_status TEXT, notes TEXT, timestamp TEXT NOT NULL)""",
            """CREATE TABLE IF NOT EXISTS system_events (
                id SERIAL PRIMARY KEY, username TEXT, event TEXT NOT NULL, details TEXT, timestamp TEXT NOT NULL)""",
        ]
        for schema in schemas:
            connection.execute(schema)
    else:
        connection.execute("""CREATE TABLE IF NOT EXISTS records (id INTEGER PRIMARY KEY AUTOINCREMENT, record_type TEXT NOT NULL, full_name TEXT NOT NULL, date_of_birth TEXT, date_of_record TEXT, father_name TEXT, mother_name TEXT, spouse_name TEXT, notes TEXT, record_details TEXT)""")
        connection.execute("""CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'Staff')""")
        connection.execute("""CREATE TABLE IF NOT EXISTS login_activity (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, username TEXT NOT NULL, action TEXT NOT NULL, timestamp TEXT NOT NULL)""")
        connection.execute("""CREATE TABLE IF NOT EXISTS record_activity (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, username TEXT NOT NULL, action TEXT NOT NULL, record_id INTEGER, record_type TEXT, record_name TEXT, timestamp TEXT NOT NULL)""")
        connection.execute("""CREATE TABLE IF NOT EXISTS certificate_requests (id INTEGER PRIMARY KEY AUTOINCREMENT, request_number TEXT UNIQUE NOT NULL, certificate_type TEXT NOT NULL, full_name TEXT NOT NULL, date_of_birth TEXT, father_name TEXT, mother_name TEXT, spouse_name TEXT, date_of_record TEXT, purpose TEXT, copies INTEGER NOT NULL DEFAULT 1, contact_information TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Pending', staff_notes TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL)""")
        connection.execute("""CREATE TABLE IF NOT EXISTS certificate_request_activity (id INTEGER PRIMARY KEY AUTOINCREMENT, request_id INTEGER NOT NULL, request_number TEXT NOT NULL, username TEXT NOT NULL, action TEXT NOT NULL, old_status TEXT, new_status TEXT, notes TEXT, timestamp TEXT NOT NULL)""")
        connection.execute("""CREATE TABLE IF NOT EXISTS system_events (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT, event TEXT NOT NULL, details TEXT, timestamp TEXT NOT NULL)""")

    if USING_POSTGRES:
        # Non-destructive production migration: add the flexible details column only.
        try:
            connection.execute("ALTER TABLE records ADD COLUMN IF NOT EXISTS record_details TEXT")
        except Exception as exc:
            print(f"DATABASE MIGRATION WARNING (PostgreSQL records): {exc}")
    else:
        # Only ADD missing columns; never recreate or clear existing records.
        ensure_sqlite_schema(connection)

    if connection.execute("SELECT id FROM users WHERE username = ?", ("admin",)).fetchone() is None:
        connection.execute("INSERT INTO users (username, password_hash, role) VALUES (?, ?, ?)", ("admin", generate_password_hash("admin123"), "Administrator"))
    connection.commit()
    connection.close()


initialize_database()

