def allowed_file(filename):
    return (
        "." in filename
        and filename.rsplit(".", 1)[1].lower() in ALLOWED_EXTENSIONS
    )


def clean_json_text(text):
    text = (text or "").strip()
    if text.startswith("```"):
        text = re.sub(r"^```(?:json)?\s*", "", text, flags=re.I)
        text = re.sub(r"\s*```$", "", text)
    start = text.find("{")
    end = text.rfind("}")
    if start != -1 and end > start:
        return text[start:end + 1]
    return text


def normalize_record_type(value):
    value = str(value or "").strip().lower()
    mapping = {
        "baptism": "Baptismal",
        "baptismal": "Baptismal",
        "baptismal certificate": "Baptismal",
        "marriage": "Marriage",
        "marriage certificate": "Marriage",
        "death": "Death",
        "death certificate": "Death",
        "confirmation": "Confirmation",
        "confirmation certificate": "Confirmation",
    }
    return mapping.get(value, "Baptismal")


def _configure_tesseract():
    """Find the Tesseract executable on Windows or Linux/Render."""
    if pytesseract is None:
        return False

    configured = os.getenv("TESSERACT_CMD", "").strip()
    if configured and os.path.exists(configured):
        pytesseract.pytesseract.tesseract_cmd = configured
        return True

    candidates = [
        r"C:\Program Files\Tesseract-OCR\tesseract.exe",
        r"C:\Program Files (x86)\Tesseract-OCR\tesseract.exe",
        "/usr/bin/tesseract",
        "/usr/local/bin/tesseract",
    ]
    for candidate in candidates:
        if os.path.exists(candidate):
            pytesseract.pytesseract.tesseract_cmd = candidate
            return True

    # If Tesseract is already in PATH, this succeeds without a fixed path.
    try:
        pytesseract.get_tesseract_version()
        return True
    except Exception:
        return False


def _ocr_line_value(text, labels):
    """Get a value written on the same line as a certificate label."""
    lines = [line.strip() for line in text.splitlines() if line.strip()]
    for i, line in enumerate(lines):
        normalized = re.sub(r"\s+", " ", line).strip()
        for label in labels:
            pattern = rf"^\s*{re.escape(label)}\s*[:\-]?\s*(.*)$"
            match = re.match(pattern, normalized, flags=re.I)
            if match:
                value = match.group(1).strip(" :-\t")
                if value:
                    return value
                if i + 1 < len(lines):
                    next_line = lines[i + 1].strip()
                    if next_line and not re.match(r"^[A-Za-z][A-Za-z '\-]+\s*[:\-]", next_line):
                        return next_line
    return ""


def _clean_ocr_value(value):
    value = re.sub(r"\s{2,}", " ", str(value or "")).strip(" \t:-")
    return value


def local_ocr_extract_document(file_storage):
    """Extract parish certificate text locally with Tesseract OCR.

    No OpenAI API, API key, or external AI request is used here.
    """
    if pytesseract is None or Image is None:
        raise RuntimeError(
            "Local OCR is not installed. Install Pillow and pytesseract, then restart Flask."
        )

    if not _configure_tesseract():
        raise RuntimeError(
            "Tesseract OCR was not found. Install Tesseract OCR on this computer/server "
            "or set the TESSERACT_CMD environment variable."
        )

    filename = file_storage.filename or ""
    if not allowed_file(filename):
        raise ValueError("Please upload PNG, JPG, JPEG, or WEBP.")

    raw = file_storage.read()
    if not raw:
        raise ValueError("The uploaded file is empty.")

    try:
        image = Image.open(io.BytesIO(raw)).convert("RGB")
        # Simple local preprocessing improves printed-document OCR.
        image = ImageOps.exif_transpose(image)
        max_width = 2200
        if image.width > max_width:
            ratio = max_width / float(image.width)
            image = image.resize((max_width, max(1, int(image.height * ratio))))
        gray = ImageOps.grayscale(image)
        gray = ImageEnhance.Contrast(gray).enhance(1.6)
        gray = gray.filter(ImageFilter.SHARPEN)

        text = pytesseract.image_to_string(
            gray,
            config="--oem 3 --psm 6",
            lang="eng",
        ).strip()
    except Exception as exc:
        raise RuntimeError(f"Local OCR could not read the document: {exc}") from exc

    if not text:
        raise RuntimeError(
            "No readable text was detected. Try a clearer, straight, well-lit certificate image."
        )

    lower = text.lower()
    if "confirmation" in lower:
        record_type = "Confirmation"
    elif "marriage" in lower or "matrimony" in lower or "nuptial" in lower:
        record_type = "Marriage"
    elif "death" in lower or "deceased" in lower or "burial" in lower:
        record_type = "Death"
    elif "baptism" in lower or "baptized" in lower or "baptised" in lower:
        record_type = "Baptismal"
    else:
        record_type = "Baptismal"

    full_name = _ocr_line_value(text, [
        "Full Name", "Name", "Name of Child", "Child's Name", "Childs Name",
        "Name of Person", "Person's Name", "Bride", "Groom", "Deceased"
    ])
    date_of_birth = _ocr_line_value(text, [
        "Date of Birth", "Birth Date", "Born", "Date Born"
    ])
    date_of_record = _ocr_line_value(text, [
        "Date of Baptism", "Date of Marriage", "Date of Death", "Date of Confirmation",
        "Date of Record", "Record Date", "Date"
    ])
    father_name = _ocr_line_value(text, ["Father's Name", "Father", "Father Name"])
    mother_name = _ocr_line_value(text, ["Mother's Name", "Mother", "Mother Name"])
    spouse_name = _ocr_line_value(text, ["Spouse's Name", "Spouse", "Spouse Name", "Husband", "Wife"])

    # Common certificate layouts use a name label without punctuation.
    if not full_name:
        for line in [x.strip() for x in text.splitlines() if x.strip()]:
            if re.match(r"^(full\s+name|name\s+of\s+(child|person))\b", line, re.I):
                full_name = re.sub(r"^[^:]+[:\-]\s*", "", line, flags=re.I).strip()
                break

    extracted = {
        "record_type": normalize_record_type(record_type),
        "full_name": _clean_ocr_value(full_name),
        "date_of_birth": _clean_ocr_value(date_of_birth),
        "date_of_record": _clean_ocr_value(date_of_record),
        "father_name": _clean_ocr_value(father_name),
        "mother_name": _clean_ocr_value(mother_name),
        "spouse_name": _clean_ocr_value(spouse_name),
        "notes": "Local OCR text:\n" + text,
    }

    return extracted


