@app.route("/system-backup", methods=["GET", "POST"])
@admin_required
def system_backup():
    if USING_POSTGRES:
        body = """
        <div class="form-box">
            <h2>Database Backup</h2>
            <p class="note">This deployed system uses Render PostgreSQL. Your parish records are stored in the hosted PostgreSQL database and are not tied to the Render service filesystem.</p>
            <p style="color:#718096">For PostgreSQL backups, use the backup tools provided by your Render PostgreSQL instance.</p>
            <a class="back" href="/">Back to Dashboard</a>
        </div>"""
        return page("Database Backup", body)

    message = None
    error = None
    backup_dir = os.path.join("database", "backups")
    os.makedirs(backup_dir, exist_ok=True)
    if request.method == "POST" and request.form.get("action") == "backup":
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        backup_name = f"parish_records_backup_{timestamp}.db"
        backup_path = os.path.join(backup_dir, backup_name)
        try:
            source = sqlite3.connect(DATABASE)
            destination = sqlite3.connect(backup_path)
            with destination:
                source.backup(destination)
            destination.close(); source.close()
            log_activity(session["user_id"], session.get("username", ""), "Created database backup")
            return send_file(backup_path, as_attachment=True, download_name=backup_name)
        except Exception as exc:
            error = f"Backup failed: {exc}"
    backups = []
    for filename in sorted(os.listdir(backup_dir), reverse=True):
        if filename.lower().endswith(".db"):
            full_path = os.path.join(backup_dir, filename)
            backups.append((filename, os.path.getsize(full_path)))
    body = f"""
    <div class="form-box"><h2>Database Backup and Restore</h2><p>Protect parish records by creating a backup before major changes.</p>
    {{"<div class='alert'>" + error + "</div>" if error else ""}}
    <form method="POST"><input type="hidden" name="action" value="backup"><button class="submit" type="submit">Create and Download Backup</button></form>
    </div>
    <div class="form-box" style="margin-top:22px"><h3>Restore Database</h3><form method="POST" action="/restore-database" enctype="multipart/form-data"><input type="file" name="database_file" accept=".db" required><button class="submit" type="submit">Restore Database</button></form><a class="back" href="/">Back to Dashboard</a></div>
    """
    return page("Database Backup and Restore", body)


@app.route("/restore-database", methods=["POST"])
@admin_required
def restore_database():
    if USING_POSTGRES:
        return page("Restore Not Available", "<div class='form-box'><div class='alert'>Direct SQLite restore is disabled while the live system is using PostgreSQL. Use the Render PostgreSQL backup/restore tools instead.</div><a class='back' href='/system-backup'>Back</a></div>"), 400
    uploaded = request.files.get("database_file")
    if not uploaded or not uploaded.filename or not uploaded.filename.lower().endswith(".db"):
        return page("Restore Failed", "<div class='form-box'><div class='alert'>Please select a valid .db backup file.</div><a class='back' href='/system-backup'>Back</a></div>"), 400
    backup_dir = os.path.join("database", "backups")
    os.makedirs(backup_dir, exist_ok=True)
    temp_path = os.path.join(backup_dir, "restore_upload_temp.db")
    try:
        uploaded.save(temp_path)
        check = sqlite3.connect(temp_path)
        integrity = check.execute("PRAGMA integrity_check").fetchone()[0]
        tables = {row[0] for row in check.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()}
        check.close()
        if integrity != "ok" or not {"records", "users", "login_activity"}.issubset(tables):
            raise ValueError("The selected file is not a valid Parish Records database.")
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        safety_path = os.path.join(backup_dir, f"before_restore_{timestamp}.db")
        if os.path.exists(DATABASE): shutil.copy2(DATABASE, safety_path)
        os.replace(temp_path, DATABASE)
        session.clear()
        return redirect(url_for("login"))
    except Exception as exc:
        if os.path.exists(temp_path): os.remove(temp_path)
        return page("Restore Failed", f"<div class='form-box'><div class='alert'>Restore failed: {escape(exc)}</div><a class='back' href='/system-backup'>Back</a></div>"), 400


