# ============================================================
# STEPS 6-20: REQUEST PROCESSING, REPORTS, EXPORT, SECURITY
# ============================================================

REQUEST_STATUSES = [
    "Pending", "Under Review", "Verified",
    "Needs Additional Information", "Ready for Release",
    "Released", "Rejected"
]


def log_certificate_request_activity(request_id, request_number, action,
                                      old_status=None, new_status=None, notes=""):
    connection = get_db_connection()
    connection.execute("""
        INSERT INTO certificate_request_activity
        (request_id, request_number, username, action, old_status, new_status, notes, timestamp)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    """, (
        request_id, request_number, session.get("username", "system"), action,
        old_status, new_status, notes, datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    ))
    connection.commit()
    connection.close()


def public_rate_limited(key):
    now = time.time()
    q = PUBLIC_RATE_LIMIT[key]
    while q and now - q[0] > PUBLIC_RATE_WINDOW:
        q.popleft()
    if len(q) >= PUBLIC_RATE_MAX:
        return True
    q.append(now)
    return False


@app.route("/certificate-requests/<int:request_id>/save-record", methods=["POST"])
@login_required
def save_certificate_request_as_record(request_id):
    """Save a verified certificate request directly into Parish Records."""
    connection = get_db_connection()
    item = connection.execute("SELECT * FROM certificate_requests WHERE id = ?", (request_id,)).fetchone()
    if item is None:
        connection.close()
        return page("Request Not Found", """
            <div class='form-box'><div class='alert'>Certificate request not found.</div>
            <a class='back' href='/certificate-requests'>Back to Certificate Requests</a></div>
        """), 404

    requested_status = request.form.get("status", "").strip()
    allowed_save_statuses = {"Verified", "Ready for Release", "Released"}
    status_changed_for_save = False

    # Save Record can complete the verification step in one action when the
    # staff member has selected an allowed status in the Request Status field.
    if item["status"] not in allowed_save_statuses:
        if requested_status not in allowed_save_statuses:
            connection.close()
            return page("Verification Required", """
                <div class='form-box'>
                    <div class='alert'>Set the Request Status to Verified before it can be saved as a parish record.</div>
                    <a class='back' href='/certificate-requests/{request_id}'>Back to Request</a>
                </div>
            """), 400

        old_status = item["status"]
        status_changed_for_save = True
        now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        connection.execute("""UPDATE certificate_requests
            SET status=?, updated_at=? WHERE id=?""",
            (requested_status, now, request_id))
        connection.execute("""
            INSERT INTO certificate_request_activity
            (request_id, request_number, username, action, old_status, new_status, notes, timestamp)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)
        """, (
            request_id, item["request_number"], session.get("username", "system"),
            "Status Updated for Save Record", old_status, requested_status,
            "Request verified through Save Record.", now
        ))
        connection.commit()
        item = connection.execute("SELECT * FROM certificate_requests WHERE id = ?", (request_id,)).fetchone()

    record_type = normalize_record_type(item["certificate_type"])
    full_name = (item["full_name"] or "").strip()
    date_of_birth = (item["date_of_birth"] or "").strip()
    date_of_record = (item["date_of_record"] or "").strip()
    father_name = (item["father_name"] or "").strip()
    mother_name = (item["mother_name"] or "").strip()
    spouse_name = (item["spouse_name"] or "").strip()

    if not full_name:
        connection.close()
        return page("Cannot Save Record", """
            <div class='form-box'><div class='alert'>The request has no full name, so it cannot be saved as a parish record.</div>
            <a class='back' href='/certificate-requests'>Back to Certificate Requests</a></div>
        """), 400

    # Prevent accidental duplicate records when the same request is clicked twice.
    duplicate = connection.execute("""
        SELECT id FROM records
        WHERE record_type = ? AND full_name = ?
          AND COALESCE(date_of_birth, '') = ?
          AND COALESCE(date_of_record, '') = ?
        LIMIT 1
    """, (record_type, full_name, date_of_birth, date_of_record)).fetchone()

    if duplicate:
        record_id = duplicate["id"]
        connection.close()
        return page("Record Already Exists", f"""
            <div class='form-box'>
                <div class='alert'>This request already matches Parish Record #{record_id}. No duplicate record was created.</div>
                <a class='button blue' href='/records'>View Parish Records</a>
                <a class='back' href='/certificate-requests/{request_id}'>Back to Request</a>
            </div>
        """)

    notes = f"Created from certificate request {item['request_number']}."
    purpose = (item["purpose"] or "").strip()
    if purpose:
        notes += f" Purpose: {purpose}"

    connection.execute("""
        INSERT INTO records
        (record_type, full_name, date_of_birth, date_of_record,
         father_name, mother_name, spouse_name, notes)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    """, (record_type, full_name, date_of_birth, date_of_record,
          father_name, mother_name, spouse_name, notes))
    connection.commit()

    saved = connection.execute("""
        SELECT id FROM records
        WHERE record_type = ? AND full_name = ?
          AND COALESCE(date_of_birth, '') = ?
          AND COALESCE(date_of_record, '') = ?
        ORDER BY id DESC LIMIT 1
    """, (record_type, full_name, date_of_birth, date_of_record)).fetchone()
    connection.close()

    record_id = saved["id"] if saved else ""
    log_certificate_request_activity(
        request_id, item["request_number"], "Saved as Parish Record",
        item["status"], item["status"], f"Parish Record ID: {record_id}"
    )
    log_activity(
        session.get("user_id"), session.get("username", ""),
        f"Saved certificate request {item['request_number']} as parish record #{record_id}"
    )
    if status_changed_for_save:
        log_activity(
            session.get("user_id"), session.get("username", ""),
            f"Updated certificate request {item['request_number']} to {item['status']} through Save Record"
        )

    return redirect(url_for("home"))


@app.route("/certificate-requests/<int:request_id>/process", methods=["POST"])
@login_required
def process_certificate_request(request_id):
    """Step 6: move a verified request through controlled processing."""
    new_status = request.form.get("status", "").strip()
    notes = request.form.get("staff_notes", "").strip()
    if new_status not in REQUEST_STATUSES:
        return page("Invalid Status", "<div class='form-box'><div class='alert'>Invalid status.</div></div>"), 400

    connection = get_db_connection()
    item = connection.execute("SELECT * FROM certificate_requests WHERE id=?", (request_id,)).fetchone()
    if item is None:
        connection.close()
        return page("Not Found", "<div class='form-box'><div class='alert'>Request not found.</div></div>"), 404

    old_status = item["status"]
    # Prevent skipping the verification stage for release/released states.
    if new_status in {"Ready for Release", "Released"} and old_status not in {"Verified", "Ready for Release", "Released"}:
        connection.close()
        return page("Verification Required", """
            <div class='form-box'><div class='alert'>The request must be Verified before it can be marked Ready for Release or Released.</div>
            <a class='back' href='/certificate-requests'>Back</a></div>"""), 400

    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    connection.execute("""UPDATE certificate_requests
        SET status=?, staff_notes=?, updated_at=? WHERE id=?""",
        (new_status, notes, now, request_id))
    connection.commit()
    connection.close()
    log_certificate_request_activity(request_id, item["request_number"], "Status Updated", old_status, new_status, notes)
    log_activity(session.get("user_id"), session.get("username", ""),
                 f"Updated certificate request {item['request_number']} from {old_status} to {new_status}")
    return redirect(url_for("certificate_request_detail", request_id=request_id))


@app.route("/certificate-requests/<int:request_id>/release", methods=["POST"])
@login_required
def release_certificate(request_id):
    """Step 8: mark a prepared certificate as released."""
    connection = get_db_connection()
    item = connection.execute("SELECT * FROM certificate_requests WHERE id=?", (request_id,)).fetchone()
    if item is None:
        connection.close()
        return page("Not Found", "<div class='form-box'><div class='alert'>Request not found.</div></div>"), 404
    if item["status"] != "Ready for Release":
        connection.close()
        return page("Release Not Allowed", "<div class='form-box'><div class='alert'>Only a request marked Ready for Release can be released.</div></div>"), 400
    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    notes = (item["staff_notes"] or "").strip()
    release_note = f"Released by {session.get('username', '')} on {now}."
    notes = (notes + "\n" + release_note).strip()
    connection.execute("UPDATE certificate_requests SET status='Released', staff_notes=?, updated_at=? WHERE id=?",
                       (notes, now, request_id))
    connection.commit()
    connection.close()
    log_certificate_request_activity(request_id, item["request_number"], "Certificate Released",
                                     item["status"], "Released", release_note)
    log_activity(session.get("user_id"), session.get("username", ""), release_note)
    return redirect(url_for("certificate_request_detail", request_id=request_id))


